            localizations = {
                en = {
                    change = {
                        "Developers' notes: For Discipline in Curse of Ula'tek, our changes are aimed at reducing the spec's reliance on procs for effective healing, improving sources of consistent damage, and improving Hero talent balance. We felt the spec was too reliant on Shadow Mend and Void Shield procs for effective healing, so we're updating Shadow Mend to be a passive upgrade to Flash Heal and adding a deterministic way to gain access to Void Shield. Additionally, Smite contributes a low amount of damage despite being frequently cast, so we're increasing its damage and updating the talent tree for easier access to Greater Smite.",
                        "New Talent: Grim Deliverance – Shadow Mend heals for 30% more and applies Atonement for an additional 4 seconds, but its cast time is increased by 0.5 seconds.",
                        "Shadow Mend's chance to trigger is no longer based on Shadow Word: Pain damage and has been redesigned to a passive upgrade – Flash Heal is upgraded to Shadow Mend, a stronger heal with a higher mana cost.",
                        "Apex Talent: Master the Darkness (Rank 3) has been updated – Mind Blast now upgrades your next Power Word: Shield to Void Shield. Void Shield's chance to trigger from Penance reduced to 15% (was 33%). Void Shield absorption reduced by 28%.",
                        "Apex Talent: Master the Darkness can now accumulate up to 2 charges.",
                        "All healing and absorption increased by 10%.",
                        "Atonement heals for 32% of damage done (was 30%).",
                        "Flash Heal healing increased by 25%.",
                        "Smite damage increased by 40%.",
                        "Inescapable Torment damage reduced by 30%.",
                        "Penance no longer applies Atonement when cast on an ally.: Developers' notes: We updated Penance to apply Atonement going into Midnight but have felt this has not been playing well as it causes too much friction between casting Penance on allies that need healing, allies that need Atonement applied, and enemies you want to deal damage to.",
                        "Ultimate Penitence damage and healing increased by 30%.",
                        "Greater Smite duration increased to 4 seconds (was 2 seconds) and is now a 1-point talent.",
                        "Hero Talents — Oracle: Unfolding Vision has been redesigned – When Power Word: Shield or Void Shield expires with absorption remaining, it jumps to a nearby injured ally instead. Can only happen once per shield.",
                        "Hero Talents — Voidweaver: Void Blast damage increased by 25%.",
                        "Hero Talents — Voidweaver: Voidwraith damage increased by 30%.",
                        "Hero Talents — Voidweaver: Void Infusion now increases Atonement healing from Void Blast and Penance by 75% while Entropic Rift is active (was 50%).",
                    },
                    name = "Priest",
                    source = "Blizzard",
                    sourceUrl = "https://news.blizzard.com/en-us/article/24293281/curse-of-ula-tek-content-update-notes#item16",
                    specialization = "Discipline",
                    terminologySourceUrls = {},
                    translatedFrom = "",
                    translationType = "official",
                },
                zhTW = {
                    change = {
                        "開發者備忘錄：For Discipline 在 Curse of Ula'tek 中，我們的改動旨在降低該專精對觸發效果以進行有效治療的依賴、改善穩定傷害的來源，並改善 Hero 天賦的平衡性。我們認為該專精對 Shadow Mend and Void Shield 觸發效果的依賴過高而無法進行有效治療，因此我們將 Shadow Mend 更新為對 Flash Heal 的被動升級，並新增了一種獲得 Void Shield 的確定性途徑。此外，Smite 儘管被頻繁施放，但造成的傷害量仍然很低，因此我們增加了其傷害並更新了天賦樹，以便更容易取得 Greater Smite。",
                        "新天賦：Grim Deliverance – Shadow Mend 治療量提高 30% 並額外施加 Atonement 4 秒，但其施法時間延長 0.5 秒。",
                        "Shadow Mend's chance to trigger is no longer based on Shadow Word：Pain傷害並已重新設計為被動升級 – Flash Heal升級為Shadow Mend，這是一個更強大的治療法術，但法力消耗較高。",
                        "Apex Talent：Master the Darkness（Rank 3）已更新——Mind Blast現在會將你的下一個Power Word：Shield升級為Void Shield。由Penance觸發Void Shield's的機率降低至15%（原為33%）。Void Shield的吸收量降低28%。",
